function UIMainChapterDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetTopRightProjection(0)    -- 防止资源条是歪的
        self:FillCurQuestInfo()
        local isMain = self:IsMainChapter()
        CfUtils.PlayAnimator(self.controller.gameObject.transform:Find("BgContainer"), (isMain and "Story" or "Challenge"))
        CfUtils.PlayAnimation(self.controller.gameObject, (isMain and "MainChapterDialog_NormalColourDefualt" or "MainChapterDialog_HardColourDefualt"))
        --有通关才会有动画
        self:PlayPassAni()
        cs_coroutine.start(function()
            if not self:IsMainChapter() then
                local ind = table.keyof(self._allQuestIds, checkString(self._curSelectId))
                self.ChapterList:MovePanelToItemByIndex(checkNumber(ind - 2))
            end
        end)
    end))
    return coWait
end

function UIMainChapterDialog:PlayPassAni(isTask)
    self._passCo = cs_coroutine.start(function()
        local passId = self:GetLastPassQuestId()
        --passId = 103260
        if passId <= 0 then
            return
        end
        local isHaveTask = QuestConfMgr:GetInstance():IsHaveTask(passId)
        
        if isHaveTask then
            CfUtils.SetActive(self.TexLine, false)

            CfUtils.SetActive(self.ImgComplete, false)
        end

        CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("UIMainChapterDialogAni")
        if not isTask then
            coroutine.yield(WaitForSeconds(0.583))
        end

        --防止动画穿帮
        local targetId= 0
        if self:IsMainChapter() then
            targetId = checkNumber(QuestConfMgr:GetInstance():GetCurNeedQuestId())
        else
            targetId = checkNumber(QuestConfMgr:GetInstance():GetCurNeedChallengeQuestId(self._curChapterId))
        end
        if targetId > passId then 
            local ind = table.keyof(self._allQuestIds, checkString(targetId))
            local go
            if checkNumber(ind) > 0 then
                go = self.ChapterList:GetShownItemByItemIndex(checkNumber(ind) - 1)
                print(go)
                if go then
                    local scr = CfUtils.GetLuaScr(go, UIMainChapterQuestNodeEnv)
                    if scr then
                        scr:Refresh(targetId, nil, true)
                    end
                end
            end
        end
        coroutine.yield(WaitForSeconds(0.5))  --页面的动画先播完 + 黑屏动画

        --local newUnlockSideType = QuestConfMgr:GetInstance():GetNewUnlockSideType(passId)
        --if checkNumber(newUnlockSideType) > 0 then
        --    self:FillCommonSidelineTaskTipsNode(checkNumber(newUnlockSideType))
        --end

        self:ClearLastPassQuestId()

        local ind = table.keyof(self._allQuestIds, checkString(self._curSelectId))
        local go
        if checkNumber(ind) > 0 then
            go = self.ChapterList:GetShownItemByItemIndex(ind - 1)
            if go then
                local scr = CfUtils.GetLuaScr(go, UIMainChapterQuestNodeEnv)
                if scr then
                    scr:RefreshSelectActive(false)
                    scr:Refresh(self._curSelectId, nil)

                    scr:PlayFinishAni()
                end
            end

            if isHaveTask then
                CfUtils.SetActive(self.TexLine, true)
                CfUtils.SetActive(self.ImgComplete, true)
                --CfUtils.PlayAnimation(self.ImgLine, "TextDescription_finish")
                CfUtils.PlayAnimation(self.ImgComplete, "TaskAndRewardImgComplete")
                coroutine.yield(WaitForSeconds(0.667))
                CfUtils.PlayAnimator(self.controller.gameObject.transform:Find("DetailsShowGroup/AimRoot"), "TaskChange")
            end
        end
        coroutine.yield(WaitForSeconds(0.34))

        --普通会有通关动画
        if self:IsMainChapter() then
            --通关一章
            if QuestConfMgr:GetInstance():IsPassChapter(self._curChapterId) then
                KTool.SetActive(self.CompleteAnim, true)

                local effectBg = self.CompleteAnim.gameObject.gameObject:GetComponent(typeof(UIEffectCapturedImage))
                effectBg:Capture()
                KCookie.Set("MainQuestLastPassChapter", self._curChapterId)

                self:FillPassChapterInfo(passId)
                coroutine.yield(WaitForSeconds(2))
                KTool.SetActive(self.CompleteAnim, false)
                KCookie.Set("LastSelectChapterId", 0)
                local cb = playerComponent:ShowFunctionUnlockDialog(Constants.CommonUnlockType.PassQuest)
                if cb then 
                    self._needClose = true
                else
                    UIModule.OpenDialog(UIArgs(Constants.UITypeIds.UIMainBattlePanelDialog), {{id = Constants.UITypeIds.UIMainChapterDialog}}, false)
                end
                CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIMainChapterDialogAni")
                return
            end
        else
            if QuestConfMgr:GetInstance():IsPassChallengeChapter(self._curChapterId) then
                KTool.SetActive(self.CompleteAnim, true)
                KCookie.Set("LastSelectHardChapterId", 0)
                local effectBg = self.CompleteAnim.gameObject.gameObject:GetComponent(typeof(UIEffectCapturedImage))
                effectBg:Capture()

                self:FillPassChapterInfo(passId)
                coroutine.yield(WaitForSeconds(2))
                KTool.SetActive(self.CompleteAnim, false)
                playerComponent:ShowFunctionUnlockDialog(Constants.CommonUnlockType.PassQuest)
                --CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIMainChapterDialogAni")
            end
        end

        local targetId = 0
        --矫正当前该打的关卡  
        if self:IsMainChapter() then
            targetId = checkNumber(QuestConfMgr:GetInstance():GetCurNeedQuestId())
        else
            targetId = checkNumber(QuestConfMgr:GetInstance():GetCurNeedChallengeQuestId(self._curChapterId))
        end

        xTry(function()
            self:HandleNewCgUnlocked(checkNumber(self._curSelectId))
        end)
        local isChange = false
        if QuestConfMgr:GetInstance():IsUnlockQuest(targetId) then
            self._curSelectId = targetId
            isChange = true
        end

        --普通关卡会有地图动画
        if isChange then
            if self:IsMainChapter() then
                --MainQuestMapMgr:GetInstance():FillQuestInfo(self._curSelectId)
            end
        end

        ind = table.keyof(self._allQuestIds, checkString(self._curSelectId))
        if checkNumber(ind) > 0 then
            go = self.ChapterList:GetShownItemByItemIndex(ind - 1)
            if go then
                local scr = CfUtils.GetLuaScr(go, UIMainChapterQuestNodeEnv)
                if scr then
                    scr:Refresh(self._curSelectId, nil)
                    scr:RefreshSelectActive(true)
                end
            end
            self.ChapterList:MovePanelToItemByIndex(ind - 2)
        end

        self._passCo = nil
        self:FillCurQuestInfo()
        playerComponent:ShowFunctionUnlockDialog(Constants.CommonUnlockType.PassQuest)
        CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIMainChapterDialogAni")
    end)
end

function UIMainChapterDialog:IsMainChapter()
    return checkNumber(self._curType) == Constants.IDType.QuestMain
end

---HandleNewCgUnlocked
---检测当前通关的关卡id是否解锁了cg
---@param questId number 当前通关的关卡id
function UIMainChapterDialog:HandleNewCgUnlocked(questId)
    ---CSV数值表/数据表-海外/新主线关卡/章节CG收集表
    local CGSettingID = AutoIds.IdSetting298
    local CGSettingIDGroup = string.format('%sIDGroup', AutoIds.IdSetting298)
    ----得到当前的章节id
    local curChapterId = QuestConfMgr:GetInstance():GetCurChapterId()
    ---@type TableML.TableFileRow
    local row = CfUtils.GetCfLine(CGSettingIDGroup, curChapterId)
    local ids = parse_strings(row:Get("ids"), ',')
    local hasNewCG = false
    for i, id in pairs(ids) do
        ---@type TableML.TableFileRow
        local trow = CfUtils.GetCfLine(CGSettingID, id)
        local unlockNum = checkNumber(trow:Get("unlockNum"))
        if unlockNum == questId then
            hasNewCG = true
            break
        end
    end
    if hasNewCG then
        local BtnChapterReward = self.BtnChapterReward
        if BtnChapterReward then
            CfUtils.SetActive(BtnChapterReward:Find("Root/ImgNew"), true)
            CfUtils.PlayAnimation(BtnChapterReward:Find("Root"), "MainChapterDialog_BtnChapterReward_New")
        end
    end
end

function UIMainChapterDialog:ShowGetItemAnimator(fromPosGo, toPosGo, time)
    if not fromPosGo or not toPosGo then return end
    time = time or 1
    local uiRootTrans = UIModule.RootCanvas

    local fromPos = CfUtils.UIWorldToScreenPos(fromPosGo, uiRootTrans)
    local toPos = CfUtils.UIWorldToScreenPos(toPosGo, uiRootTrans)
    local disX = (toPos.x) - (fromPos.x)
    local disY = (toPos.y) - (fromPos.y)

    local curPos = fromPosGo.transform.localPosition
    local targetPos = Vector3(curPos.x + disX, curPos.y + disY, 0)
    CfUtils.DoTween(time, function(updateValue)
        fromPosGo.transform:GetComponent(typeof(RectTransform)).localPosition = Vector3.Lerp(curPos, targetPos, updateValue)
    end,function()
        --GameObject.Destroy(itemGo)
    end)
end

