--矫正一次当前应该选的ID
function UIMainChapterDialog:RefreshCurSelectId()
    if checkNumber(self._curSelectId) <= 0 then
        if self:IsMainChapter() then
            self._curSelectId = checkNumber(QuestConfMgr:GetInstance():GetCurChapterNeedQuestId(self._curChapterId))
        else
            self._curSelectId = checkNumber(QuestConfMgr:GetInstance():GetCurNeedChallengeQuestId(self._curChapterId))
        end
    end

    --强行矫正一次上一次打过的
    --通关优先
    local id = self:GetLastPassQuestId()
    if id > 0 then
        self._curSelectId = id   --准备播动画

        --把选择的清空掉
        self:GetLastChallengeQuestId()
    --再判断挑战
    else
        id = self:GetLastChallengeQuestId()
        if id > 0 then
            self._curSelectId = id
        end
    end
end

function UIMainChapterDialog:InitData()
    self._allQuestIds = {}
    if self:IsMainChapter() then
        self._allQuestIds = QuestConfMgr:GetInstance():GetChapterIds(self._curChapterId)
    else
        self._allQuestIds = QuestConfMgr:GetInstance():GetChallengeChapterIds(self._curChapterId)
    end
end

function UIMainChapterDialog:FillSelf()
    self:FillChapterInfo()
    CfUtils.SetActive(self.BtnChapterReward.gameObject,self:IsMainChapter())
    if self:IsMainChapter() then
        CfUtils.SetActive(self.BtnMopUp.gameObject,false)
        self:OnBtnStory(true)
    else
        self:OnBtnChallenge(true)
        local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id246)
        local isBoss = self:IsBoss()
        KTool.SetActive(self.BtnMopUp.gameObject,isUnlock and isBoss)
    end
end

--章节信息
function UIMainChapterDialog:FillChapterInfo()
    local vo = self:IsMainChapter() and QuestConfMgr:GetInstance():GetChapterVoByID(self._curChapterId) or QuestConfMgr:GetInstance():GetHardChapterVoByID(self._curChapterId)
    if not vo then
        return
    end
    CfUtils.FillText(self.TxtNumber, vo.number)

    local chaptername = string.gsub(vo.name, '\\n', '')
    CfUtils.FillText(self.TxtName, chaptername)
    CfUtils.FillImage(self.Bg, vo.mapImage)
end

function UIMainChapterDialog:OnBtnStory(isEnforce)
    if self._isPlayAni then
        return
    elseif not isEnforce and self:IsMainChapter() then
        return
    end

    self._curType = Constants.IDType.QuestMain
    if not isEnforce then
        self._curSelectId = 0
        self:InitData()
    end

    self:RefreshCurSelectId()

    if self._lastSelectQuestId then
        self._curSelectId = self._lastSelectQuestId
    end
    self:FillModelInfo()
end

function UIMainChapterDialog:OnBtnChallenge(isEnforce)
    local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockChallengeChapter(self._curChapterId)
    if not isUnlock then
        GameUtils.Toast(err) 
        return
    end

    if self._isPlayAni then
        return
    elseif not isEnforce and (not self:IsMainChapter()) then
        return
    end
    self._curType = Constants.IDType.QuestMainChallenge
    if not isEnforce then
        self._curSelectId = 0
        self:InitData()
    end
    self:RefreshCurSelectId()
    self:FillModelInfo()
end

function UIMainChapterDialog:FillModelInfo()
    local isStory = self:IsMainChapter()
    self._co = cs_coroutine.start(function()
        self._isPlayAni = true

        self:FillAllQuestNode()
        while not self.ChapterList:IsAllPoolReady() do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end

        local aniName = isStory and "Story" or "Challenge"
        CfUtils.PlayAnimator(self.BtnSecondTabel, aniName)
        CfUtils.PlayAnimator(self.ChapterList, aniName)

        --MainQuestMapMgr:GetInstance():FillQuestInfo(self._curSelectId)
        local ind = table.keyof(self._allQuestIds, checkString(self._curSelectId))
        self.ChapterList:MovePanelToItemByIndex(checkNumber(ind - 2))
        coroutine.yield(WaitForSeconds(0.34))
        self._isPlayAni = false
    end)
end


function UIMainChapterDialog:FillStarsInfo()
    local t = QuestConfMgr:GetInstance():GetChapterStarInfo(self._curChapterId)
    for i = 1, #t do
        local go = self["Node"..i]
        self:FillStarInfo(go, t[i], i)
    end
end

function UIMainChapterDialog:FillStarInfo(go, data, ind)
    if not go or not data then
        return
    end

    CfUtils.FillText(go.transform:Find("Layout/TextNumber"), data.starNum)
    CfUtils.FillImage(go.transform:Find("ImgIcon"), GoodsConfMgr:GetInstance():GetPhotoPathById(data.goodsId))

    local isDraw = QuestConfMgr:GetInstance():IsDrawChapterReward(self._curChapterId, data.ind)
    local IsCanDrawChapterReward = QuestConfMgr:GetInstance():IsCanDrawChapterReward(self._curChapterId, data.ind)

    local aniName = IsCanDrawChapterReward and "UIFX_MainChapterDialogRewardNode"..ind.."CanReceived" or "UIFX_MainChapterDialogRewardNode"..ind.."Idle"
    local ani = go.transform:Find("ImgIcon"):GetComponent(typeof(Animation))
    if ani then
        ani:Play(aniName)
    end

    --go.transform:Find("ImgIcon").transform:GetComponent(typeof(CS.Engine.UI.UIGrayGraphics)):MarkGray(isDraw)

    KTool.SetActive(go.transform:Find("CanReceive"), IsCanDrawChapterReward)
    KTool.SetActive(go.transform:Find("HasReceived"), isDraw)

    local t1 = CfUtils.Split(data.goodsId)
    local t2 = CfUtils.Split(data.num)
    local t = {}
    for k, v in pairs(t1) do
        local data = 
        {
            goodsId = t1[k],
            num = t2[k],
        }
        table.insert(t, data)
    end

    SetButtonAction(go, function()
        if isDraw then
            GameUtils.ShowCommonTipsBoardRewardPreview(go.gameObject, t, localize('奖励预览:'), true)
            return
        elseif not IsCanDrawChapterReward then
            GameUtils.ShowCommonTipsBoardRewardPreview(go.gameObject, t, localize('奖励预览:'), false)
            return
        end 
        questComponent:MainQuestChapterStartRewardReq(self._curChapterId, data.ind, function()
            self:FillRedPoint()
        end)
    end)
end

function UIMainChapterDialog:FillAllQuestNode()
    if not self._isInitList then
        self.ChapterList:InitGridView(#self._allQuestIds, Bind(self, self.OnGetItemByIndex))
        self._isInitList = true
    else
        GameUtils.ReloadData(self.ChapterList, #self._allQuestIds)
    end
end

---左侧每一个toggle
function UIMainChapterDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("MapCheckpointNode")
    local scr = CfUtils.GetLuaScr(cell.gameObject, UIMainChapterQuestNodeEnv)

    local id = self._allQuestIds[index + 1]
    if scr then
        scr:Refresh(id, function()

            local levelType = GoodsUtils.GetIdType(id, Constants.IDArea.Quests)
            local isChallenge = checkBool(levelType == Constants.IDType.QuestMainChallenge)

            if isChallenge then
                self:ChooseQuest(id)
                if self:IsMainChapter() then
                    self._lastSelectQuestId = id
                end
            else
                local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(id)
                if not isUnlock then
                    GameUtils.Toast(self:GetUnlockErr(id))
                    return
                end
                self:ChooseQuest(id)
                if self:IsMainChapter() then
                    self._lastSelectQuestId = id
                end
            end
        end)

        if checkNumber(self._curSelectId) == checkNumber(id) then
            CfUtils.PlayAnimator(cell.gameObject, "In")
        else
            CfUtils.PlayAnimator(cell.gameObject, "Idle")
        end 
    end

    return cell
end

--选择
function UIMainChapterDialog:ChooseQuest(questId)
    if checkNumber(questId) == checkNumber(self._curSelectId) then
        return
    end

    questId = checkString(questId)
    local ind = table.keyof(self._allQuestIds, checkString(self._curSelectId))

    local go
    if checkNumber(ind) > 0 then
        go = self.ChapterList:GetShownItemByItemIndex(ind - 1)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIMainChapterQuestNodeEnv)
            if lastScr then
                lastScr:RefreshSelectActive(false)
            end
        end
    end

    self._curSelectId = questId
    ind = table.keyof(self._allQuestIds, checkString(self._curSelectId))
    if checkNumber(ind) > 0 then
        go = self.ChapterList:GetShownItemByItemIndex(ind - 1)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIMainChapterQuestNodeEnv)
            if lastScr then
                lastScr:RefreshSelectActive(true)
            end
        end
    end

    --MainQuestMapMgr:GetInstance():FillQuestInfo(self._curSelectId)
    self:FillCurQuestInfo()
    CfUtils.PlayAnimator(self.controller.gameObject.transform:Find("DetailsShowGroup/AimRoot"), "Change")
end

--播放当前音乐
function UIMainChapterDialog:PlayCurBgm()
    local plotVo = QuestConfMgr:GetInstance():GetMainQuestPlotVo(self._curSelectId)
    if not plotVo then
        return
    end

    --没配
    if checkString(plotVo.bgm) == "" then
        CriWareUtils.PlayRandomBGMFromCDList()
    else
        CriWareUtils.PlayMusicById(checkString(plotVo.bgm))
    end
end

--这个关卡的剧情是否已经看过
function UIMainChapterDialog:IsShowCurQuestStory()
    local str = CfUtils.GetLocalData("MainQuestTaskStory") 
    local t = checkTable(CfUtils.Split(str))
    for k, v in pairs(t) do
        if checkNumber(v) == checkNumber(self._curSelectId) then
            return true
        end
    end
    return false
end

function UIMainChapterDialog:FillCurQuestInfo()
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectId)
    if not vo then
        return
    end
    local chaptername = string.gsub(vo.name, '\\n', '')
    --CfUtils.FillText(self.TxtNum, vo.label)
    CfUtils.FillText(self.TextName2, chaptername)
    CfUtils.SetActive(self.Plot, (checkNumber(vo.type) == Constants.QuestBattleType.Story))
    CfUtils.SetActive(self.Task1, (checkNumber(vo.type) == Constants.QuestBattleType.Task) or (checkNumber(vo.type) == Constants.QuestBattleType.StoryTask))
    CfUtils.SetActive(self.Fight, (checkNumber(vo.type) == Constants.QuestBattleType.Battle) or (checkNumber(vo.type) == Constants.QuestBattleType.All))
    CfUtils.SetActive(self.ImgBoss, (checkNumber(vo.monsteType) == Constants.RoleClass.Boss))
    --CfUtils.SetActive(self.UIFX_MainChapterDialogStateSwitch, false)
    local plotVo = QuestConfMgr:GetInstance():GetMainQuestPlotVo(self._curSelectId)
    if not plotVo then
        return
    end

    local chapterGeneralVo = self:GetChapterGeneralVo(plotVo.desc)
    if chapterGeneralVo then
        CfUtils.SetActive(self.TextDesc3, true)
        CfUtils.FillText(self.TextDesc3, self:GetBtnStoryInfo())
    else
        CfUtils.SetActive(self.TextDesc3, false)
    end
    CfUtils.FillImage(self.ImgChapter, plotVo.image, true)

    if self:IsMainChapter() then
        self:FillHeadsTest()
        local isHaveTask = QuestConfMgr:GetInstance():IsHaveTask(self._curSelectId)
        CfUtils.SetActive(self.TaskReceive, isHaveTask)
        CfUtils.SetActive(self.BtnChallengeNode.gameObject,false)
        if isHaveTask then
            self:FillTaskInfo()
        else
            CfUtils.SetActive(self.RightPanel, true)
            local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._curSelectId)
            if isPass then
                CfUtils.PlayAnimator(self.RightPanel, "UIMainChapterBtnReviewDefault")
                CfUtils.SetUISwitchText(self.BtnNode.transform:Find("Text"), 3)
                CfUtils.SetUISwitchText(self.BtnNode.transform:Find("TextBtnStaus"), 3)
                CfUtils.SetUISwitchImage(self.BtnNode.transform:Find("ImgBg2"), 3)
            else
                CfUtils.SetUISwitchText(self.BtnNode.transform:Find("Text"), 1)
                CfUtils.SetUISwitchText(self.BtnNode.transform:Find("TextBtnStaus"), 1)
                CfUtils.SetUISwitchImage(self.BtnNode.transform:Find("ImgBg2"), 1)
                CfUtils.PlayAnimator(self.RightPanel, "UIMainChapterBtnStart1")
            end
        end
    else
        CfUtils.SetActive(self.TextDesc3, false)
        CfUtils.SetActive(self.TaskReceive, false)
        local consumeGold = checkNumber(vo.costItem)
        KTool.SetActive(self.CommonBtnConsumePop.gameObject, consumeGold > 0)
        if consumeGold > 0 then
            UICommonUtils.FillCommonBtnConsumePop(self.CommonBtnConsumePop, consumeGold, vo.costNum)
        end
        self:RefreshLeaveTimes()
        local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._curSelectId)
        if not isPass then
            CfUtils.SetActive(self.BtnChallengeNode.gameObject,true)
        else
            local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectId)
            if not isNull(vo) and (checkNumber(vo.monsteType) == Constants.RoleClass.Boss) then
                CfUtils.SetActive(self.BtnChallengeNode.gameObject,true)
            else
                CfUtils.SetActive(self.BtnChallengeNode.gameObject,false)
            end
        end
    end

    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsListNode)
    if scr then
        if self:IsMainChapter() then
            local rewardData = RewardConfMgr:GetTeamShowRewardData(self._curSelectId)
            scr:FreshBaseUI(rewardData, false)
            local isDraw = QuestConfMgr:GetInstance():IsPassQuest(self._curSelectId)
            scr:SetIsGetMaskShow(isDraw)
        else
            local rewardData = RewardConfMgr:GetTeamShowRewardData(self._curSelectId)
            local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectId)
            local isDraw = QuestConfMgr:GetInstance():IsPassQuest(self._curSelectId)

            if not isNull(vo) and (checkNumber(vo.monsteType) == Constants.RoleClass.Boss) then
                for i, v in pairs(rewardData) do
                    if v.type == Constants.RewardSourceType.FirstPass then
                        v.isGet = isDraw and true or false
                    else
                        v.isGet = false
                    end
                end
                scr:FreshBaseUI(rewardData, false)
                scr:SetIsGetMaskShowByData(isDraw)
            else
                scr:FreshBaseUI(rewardData, false)
                scr:SetIsGetMaskShow(isDraw)
            end
        end
    end

    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._curSelectId)
    CfUtils.SetActive(self.ImgComplete, isPass)
end

function UIMainChapterDialog:RefreshLeaveTimes()
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectId)
    if not isNull(vo) and (checkNumber(vo.monsteType) == Constants.RoleClass.Boss) then
        CfUtils.SetActive(self.TextNumOfTime,true)
        ---@type QuestComponent
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
        local totalRewardTime = comp:GetChallengeTotalTimes()
        local havePassTime = comp:GetChallengePassedTimes()
        local leaveTime = totalRewardTime - havePassTime
        CfUtils.FillText(self.TextNumOfTime,localize("剩余奖励次数：_num_",{_num_ = string.format("<color=#FF69CE>%s</color>",leaveTime)}))
    else
        CfUtils.SetActive(self.TextNumOfTime,false)
    end
end

function UIMainChapterDialog:OnBtnTask()
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectId)
    local data = questComponent:GetCurTaskInfo()
    local isDraw = checkNumber(data.id) > 0
    local isFinish = QuestConfMgr:GetInstance():IsMainTaskCanDraw(self._curSelectId)

    --没领
    if not isDraw then
        questComponent:TaskMainTaskReceivingReq(vo.task, self._curSelectId, function()
            local plotVo = QuestConfMgr:GetInstance():GetMainQuestPlotVo(self._curSelectId)
            local t = checkTable(CfUtils.Split(plotVo.taskPlotId))
            local plotIds = {}
            for k, v in pairs(t) do
                if checkNumber(v) > 0 then
                    table.insert(plotIds, v)
                end
            end

            local isHasStoryEntry = (table.count(plotIds) > 0) 
            if isHasStoryEntry then
                local isShowStory = self:IsShowCurQuestStory()
                --起一个剧情
                if not isShowStory then
                    local str = CfUtils.GetLocalData("MainQuestTaskStory") 
                    CfUtils.WriteLocalData("MainQuestTaskStory", str..";"..plotVo.id) 

                    self:PlayPlot(vo, function()
                        self:FillCurQuestInfo()
                        --CfUtils.SetActive(self.UIFX_MainChapterDialogStateSwitch, true)
                        self:PlayDrawTaskAni()
                    end, true, 1)
                else
                    self:FillCurQuestInfo()
                    --CfUtils.SetActive(self.UIFX_MainChapterDialogStateSwitch, true)
                    self:PlayDrawTaskAni()
                end
            else
                self:FillCurQuestInfo()
                --CfUtils.SetActive(self.UIFX_MainChapterDialogStateSwitch, true)
                self:PlayDrawTaskAni()
            end
        end)
    else
        local taskVo = QuestConfMgr:GetInstance():GetMainTaskQuestVo(vo.task)
        local isSpecialType = checkNumber(taskVo.taskContentType) == Constants.TaskType.Submittals
        --已完成
        if isFinish or isSpecialType then
            --特殊任务类型 提交材料
            if isSpecialType then
                if GoodsUtils.GetThingNo(taskVo.taskContentId) < checkNumber(taskVo.taskContenNum) then
                    GameUtils.Toast(localize("材料不足"))
                    return 
                end
            end

            if isSpecialType then
                local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(taskVo.taskContentId)
                vo.goodsId = vo.id
                vo.forceText = taskVo.taskContenNum
                vo.num = checkNumber(taskVo.taskContenNum)

                GameUtils.SecondConfirm(localize("确认提交以下道具并领取任务奖励？"), function()
                    self:OnTaskSubmit()
                end, nil, nil, 4, {vo}, nil, localize("该道具将从仓库中直接消耗"))
            else
                self:OnTaskSubmit()
            end
        end
    end
end

