function UIMainChapterDialog:PlayDrawTaskAni()
    if self._taskCo then
        cs_coroutine.stop(self._taskCo)
        self._taskCo = nil
    end
    self._taskCo = cs_coroutine.start(function()
        CfUtils.SetActive(self.TaskTarget, false)
        CfUtils.SetActive(self.TaskAnalysis, true)
        CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("PlayDrawTaskAni")
        CfUtils.PlayAnimation(self.TaskAnalysis, "TaskAnalysis_End")
        coroutine.yield(WaitForSeconds(0.367))
        CfUtils.SetActive(self.TaskAnalysis, false)
        CfUtils.SetActive(self.TaskTarget, true)
        CfUtils.PlayAnimation(self.TaskTarget, "TaskReceive_TaskTarget_go")
        CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("PlayDrawTaskAni")
    end)

    if self._btnCo then
        cs_coroutine.stop(self._btnCo)
        self._btnCo = nil
    end
    self._btnCo = cs_coroutine.start(function()
        CfUtils.PlayAnimator(self.RightPanel, "FontStyleButtonRoot_Out")
        coroutine.yield(WaitForSeconds(0.25))
        local isFinish = QuestConfMgr:GetInstance():IsMainTaskCanDraw(self._curSelectId)
        --已完成
        if isFinish then
            CfUtils.PlayAnimator(self.RightPanel, "UIMainChapterBtnStart2")
        else
            CfUtils.PlayAnimator(self.RightPanel, "UIMainChapterBtnStart1")
        end
    end)
end

--提交任务
function UIMainChapterDialog:OnTaskSubmit()
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectId)
    local taskVo = QuestConfMgr:GetInstance():GetMainTaskQuestVo(vo.task)
    local isSpecialType = checkNumber(taskVo.taskContentType) == Constants.TaskType.Submittals

    questComponent:TaskMainTaskSubmitReq(self._curSelectId, function(rewards)
        --特殊任务要扣道具
        if isSpecialType then
            GoodsUtils.DrawRewards({ { goodsId = taskVo.taskContentId, num = -checkNumber(taskVo.taskContenNum) } })
        end

        --CfUtils.SetActive(self.UIFX_MainChapterDialogStateSwitch, false)
        --是否有结尾剧情
        local plotVo = QuestConfMgr:GetInstance():GetMainQuestPlotVo(self._curSelectId)

        local plotIds = {}
        local t = checkTable(CfUtils.Split(plotVo.taskPlotEndId))
        for k, v in pairs(t) do
            if checkNumber(v) > 0 then
                table.insert(plotIds, v)
            end
        end
        local goodsId = string.split(self.controller.goodIds, ";")
        if table.count(plotIds) > 0 then
            self:PlayPlot(vo, function()
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards, cb = function()
                    if rewards then
                        for i, v in pairs(rewards) do
                            for i, gId in pairs(goodsId) do
                                if checkNumber(v.goodsId) == checkNumber(gId) then
                                    GameUtils.StartFlyGoods(self.CommonGoodsList.gameObject, checkNumber(v.goodsId))
                                end
                            end
                        end
                    end
                    self:PlayPassAni(true)
                    self:PlayDrawRwardAni()
                    self:SetMainChapterBGM(self._curSelectId)
                end } })
            end, true, 2)
        else
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards, cb = function()
                if rewards then
                    for i, v in pairs(rewards) do
                        for i, gId in pairs(goodsId) do
                            if checkNumber(v.goodsId) == checkNumber(gId) then
                                GameUtils.StartFlyGoods(self.CommonGoodsList.gameObject, checkNumber(v.goodsId))
                            end
                        end
                    end
                end
                self:PlayPassAni(true)
                self:PlayDrawRwardAni()
                self:SetMainChapterBGM(self._curSelectId)
            end } })
        end
    end)
end

--有任务
function UIMainChapterDialog:FillTaskInfo()
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectId)
    local taskVo = QuestConfMgr:GetInstance():GetMainTaskQuestVo(vo.task)
    CfUtils.FillText(self.TxtName3, tostring(vo.name))

    CfUtils.FillText(self.TextDesc, taskVo.taskTitle)
    --已通关算完成
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._curSelectId)
    CfUtils.SetActive(self.Slider1, not isPass)
    CfUtils.SetActive(self.TexLine, isPass)

    CfUtils.SetActive(self.RightPanel, true)
    if isPass then
        --CfUtils.FillText(self.TextNumer, taskVo.taskContenNum.."/"..taskVo.taskContenNum)
        CfUtils.SetActive(self.TextNumer, false)

        --有剧情显示回顾
        if checkNumber(vo.type) == Constants.QuestBattleType.StoryTask then
            --CfUtils.SetActive(self.BtnStart, true)
            --CfUtils.PlayAnimator(self.BtnStart, "Loop")
            --CfUtils.SetActive(self.FontStyleButton1, false)
            CfUtils.PlayAnimator(self.RightPanel, "UIMainChapterBtnReviewDefault")

            CfUtils.SetUISwitchText(self.BtnNode.transform:Find("Text"), 3)
            CfUtils.SetUISwitchText(self.BtnNode.transform:Find("TextBtnStaus"), 3)
            CfUtils.SetUISwitchImage(self.BtnNode.transform:Find("ImgBg2"), 3)
        else
            CfUtils.SetActive(self.RightPanel, false)
            --CfUtils.SetActive(self.BtnStart, false)
            --CfUtils.SetActive(self.FontStyleButton1, false)
        end

        CfUtils.SetActive(self.TaskAnalysis, false)
        CfUtils.SetActive(self.TaskTarget, true)
    else
        local data = questComponent:GetCurTaskInfo()
        --if checkNumber(vo.type) == Constants.QuestBattleType.StoryTask then
        --end
        local isDraw = checkNumber(data.id) > 0
        local isFinish = QuestConfMgr:GetInstance():IsMainTaskCanDraw(self._curSelectId)
        CfUtils.SetActive(self.TaskTarget, isDraw)
        CfUtils.SetActive(self.TaskAnalysis, not isDraw)
        --没领任务
        if not isDraw then
            CfUtils.SetActive(self.TextNumer, true)
            CfUtils.FillText(self.TextNumer, "???????????")

            CfUtils.PlayAnimator(self.RightPanel, "FontStyleButtonRoot_Entry")
            --CfUtils.SetActive(self.BtnStart, false)
            --CfUtils.SetActive(self.FontStyleButton1, true)
            self.FontStyleButton1:ResetFontStyle("B6", localize("接取任务"))
        else
            CfUtils.FillText(self.TextDesc, taskVo.taskTitle)
            CfUtils.SetActive(self.TextNumer, true)

            if checkNumber(taskVo.taskContentType) == Constants.TaskType.Submittals then
                CfUtils.FillText(self.TextNumer, "("..GoodsUtils.GetThingNo(taskVo.taskContentId).."/"..taskVo.taskContenNum..")")
            else
                CfUtils.FillText(self.TextNumer, "("..data.progress.."/"..taskVo.taskContenNum..")")
            end
            self.Slider1.value = checkNumber(data.progress) / checkNumber(taskVo.taskContenNum)
                --已完成
                if isFinish then
                    CfUtils.PlayAnimator(self.RightPanel, "UIMainChapterBtnStart2")
                    --CfUtils.SetActive(self.BtnStart, true)
                    --CfUtils.SetActive(self.FontStyleButton1, false)
                    --CfUtils.PlayAnimator(self.BtnStart, "CanGetReward")
                    CfUtils.SetUISwitchText(self.BtnNode.transform:Find("Text"), 2)
                    CfUtils.SetUISwitchText(self.BtnNode.transform:Find("TextBtnStaus"), 2)
                    CfUtils.SetUISwitchImage(self.BtnNode.transform:Find("ImgBg2"), 2)

                    CfUtils.SetUISwitchText(self.TextNumer, 2)
                else
                    CfUtils.PlayAnimator(self.RightPanel, "UIMainChapterBtnStart1")
                    --CfUtils.SetActive(self.BtnStart, true)
                    --CfUtils.PlayAnimator(self.BtnStart, "Loop")
                    --CfUtils.SetActive(self.FontStyleButton1, false)

                    CfUtils.SetUISwitchImage(self.BtnNode.transform:Find("ImgBg2"), 1)
                    CfUtils.SetUISwitchText(self.BtnNode.transform:Find("Text"), 1)
                    CfUtils.SetUISwitchText(self.BtnNode.transform:Find("TextBtnStaus"), 1)

                    CfUtils.SetUISwitchText(self.TextNumer, 1)
                end
            --end
        end
    end

    local goText = self.TextDesc.transform:GetComponent(typeof(CS.UnityEngine.UI.Text))
    CfUtils.FillText(self.TextDesc, string.gsub(goText.text, " ", "\u{00A0}") )
    self.TexLine:CreateLink(goText)
end

--主线关卡头像索引表
function UIMainChapterDialog:GetMmainQuestHeadInfoVo(id)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting2533, "MmainQuestHeadInfoVo", id)
    return vo
end

function UIMainChapterDialog:GetHeadPath(id)
    id = checkNumber(id)
    if id <= 0 then
        return
    end

    local vo = self:GetMmainQuestHeadInfoVo(id)
    if not vo then
        return nil
    end
    if id == 1 then
        if checkNumber(playerComponent.playerDojo.gender) == Constants.PLAYER_GENDER.FEMALE then
            return vo.femaleHeadUI
        else
            return vo.maleHeadUI
        end
    else
        return vo.headUI
    end
    return nil
end

--回收资源
function UIMainChapterDialog:CollectionHeadInfo()
    if isNull(self._curHeadInfo) then
        return
    end
    for k, v in pairs(self._curHeadInfo) do
        self:PushGo(v.path, v.go)
    end
end

function UIMainChapterDialog:PushGo(path, go)
    if isNull(go) then
        return
    end

    if not self._headPool then
        self._headPool = {}
    end
    path = checkString(path)
    if isNull(self._headPool[path]) then
        self._headPool[path] = {}
    end

    table.insert(self._headPool[path], go)
    KTool.SetActive(go, false)
end

function UIMainChapterDialog:FillHeadsTest()
    if self._headCo then
        cs_coroutine.stop(self._headCo)
        self._headCo = nil
    end

    self._headCo = cs_coroutine.start(function()
        --local goLoader = ResourceModule.LoadBundleSync("Prefabs/MainChapter/MainQuestHeadNode.prefab", nil, true)

        local vo = QuestConfMgr:GetInstance():GetMainQuestPlotVo(self._curSelectId)
        if not vo then
            return
        end

        local t = CfUtils.Split(vo.head)
        if not t then
            return
        end

        local parent = self.controller.gameObject.transform:Find("Container/MapNodes/Content")

        for i = 1, parent.transform.childCount do
            local child = parent.transform:GetChild(i-1)
            KTool.SafeDelete(child.gameObject)
        end

        for i = 1, #t do
            local path, bgColor = self:GetHeadInfo(t[i])
            if not bgColor then
                bgColor = "#ff0000"
            end
            cs_coroutine.yield_return(self:FillHeadInfoTest(t[i], path, bgColor, parent))
        end

        for i = 1, #t do
            local go = self._headPool[t[i]].transform:Find("AnimRoot")
            CfUtils.PlayAnimation(go, "MainQuestHeadNode_Active")
            cs_coroutine.yield_return(WaitForSeconds(0.2))
        end

        self._headCo = nil
    end)
end

function UIMainChapterDialog:FillHeadInfoTest(id, path, bgColor, parent)
    local goLoader = ResourceModule.LoadBundleSync("Prefabs/MainChapter/MainQuestHeadNode.prefab", nil, true)
    if goLoader.IsSuccess then
        local go = GameObject.Instantiate(goLoader.ResultObject, parent)
        self._headPool[id] = go
        local imgBg = go.transform:Find("AnimRoot/ImgBg")
        local imgIcon = go.transform:Find("AnimRoot/ImgHeadIcon")
        CfUtils.FillImage(imgIcon, path)
        imgBg:GetComponent(typeof(CS.UnityEngine.UI.Image)).color = XLuaUtils.HexToColor(bgColor)
    end
end

---@return string, string @ 头像资源路径， 头像底色
function UIMainChapterDialog:GetHeadInfo(id)
    local headVo = self:GetMmainQuestHeadInfoVo(id)
    if not headVo then
        return nil, nil
    end
    local headPath = nil
    local bgColor = headVo.backColor

    if checkString(id) == "1" then
        if checkNumber(playerComponent.playerDojo.gender) == Constants.PLAYER_GENDER.FEMALE then
            headPath = headVo.femaleHead
        else
            headPath = headVo.maleHead
        end
    else
        headPath = headVo.head
    end

    return headPath, bgColor
end

function UIMainChapterDialog:FillHeadInfo(path, id, groupId, pos)
    if not path then
        return
    end

    local go = self:GetGo(path)
    if isNull(go) then
        return
    end

    KTool.SetActive(go, true)

    go.transform:SetAsFirstSibling()
    --CfUtils.PlaySpine(go, "animation", true)
    --添加到缓冲
    table.insert(self._curHeadInfo, {
        path = path, 
        id = id,
        go = go,
    })
end

function UIMainChapterDialog:GetGo(path)
    if not self._headPool then
        self._headPool = {}
    end
    path = checkString(path)
    if isNull(self._headPool[path]) then
        self._headPool[path] = {}
    end
    local t = self._headPool[path]
    if isNull(t[1]) then
        local go = GameUtils.LoadBundleAsync(path, self.controller.gameObject.transform:Find("Container/MapNodes/Content"))
        return go
    end

    local go = t[1]
    table.remove(t, 1)
    return go
end

function UIMainChapterDialog:GetLoader(path)
    if not self._loaderPool then
        self._loaderPool = {}
    end
    path = checkString(path)
    if isNull(self._loaderPool[path]) then
        local loader = GameUtils.LoadBundleAsync(path)
        if loader.IsSuccess then
            self._loaderPool[path] = loader
        else
            loader:Release()
            return nil
        end
    end
    return self._loaderPool[path]
end

function UIMainChapterDialog:GetBtnStoryInfo()
    local plotVo = QuestConfMgr:GetInstance():GetMainQuestPlotVo(self._curSelectId)
    if not plotVo then
        return ""
    end

    local vo = self:GetChapterGeneralVo(plotVo.desc)
    if not vo then
        return ""
    end
    return vo.desc
end


function UIMainChapterDialog:OnBtnEnter()
    if checkNumber(self._curSelectId) <= 0 then
        return
    end
    if checkInt(self._curSelectId) >= 101090 then
        local ThirdDownloadManager = import("Game.Entry.ThirdDownloadManager"):GetInstance()
        if ThirdDownloadManager:IsNotDwonloadingEnd() and ThirdDownloadManager:IsDownloadAndPlaying() then
            GameUtils.Toast(localize("资源下载中 ...， 请等待"))  
            return  
        elseif ThirdDownloadManager:IsNotDwonloadingEnd() and (not ThirdDownloadManager:IsDownloadAndPlaying()) then
            ThirdDownloadManager:DownloadSignalPackage(localize("请调查官下载完整资源，体验后续关卡"))
            return  
        end
    end
    local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(self._curSelectId)
    if not isUnlock then
        GameUtils.Toast(self:GetUnlockErr(self._curSelectId))
        return
    end
    cs_coroutine.start(function()
        --普通才有剧情
        if self:IsMainChapter() then
            coroutine.yield(MainQuestMapMgr:GetInstance():PlayQuestStory(self._curSelectId, 1, function()
                self:EnterQuest(self._curSelectId)
            end))
        else

            local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectId)
            if not isNull(vo) and checkNumber(vo.monsteType) == Constants.RoleClass.Boss then
                ---@type QuestComponent
                local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
                local isCanEnter = comp:IsCanEnterHardChapter()
                if isCanEnter then
                    self:EnterQuest(self._curSelectId)
                else
                    GameUtils.Toast(localize("剩余奖励次数不足"))
                end
            else
                self:EnterQuest(self._curSelectId)
            end
        end
    end)
end

--剧情关卡入口
function UIMainChapterDialog:OnTaskEnter(id)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
    local data = questComponent:GetCurTaskInfo()
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._curSelectId)
    if isPass then
        if checkNumber(vo.type) == Constants.QuestBattleType.StoryTask then
            --只播剧情
            self:PlayPlot(vo, function()
            end, true, 3)
        end
    else
        local isFinish = QuestConfMgr:GetInstance():IsMainTaskCanDraw(self._curSelectId)
        --领取奖励
        if isFinish then
            self:OnBtnTask()
        else
            local taskVo = QuestConfMgr:GetInstance():GetMainTaskQuestVo(vo.task)
            local goodsConfMgr = GoodsConfMgr:GetInstance()
            local row = goodsConfMgr:GetJumpModuleRow(taskVo.openType)
            local functionID = checkInt(row:Get("functionID"))
            local function jumpToTask()
                local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
                blocker:AddCondition("__ExecuteJump")
                xTry(function()
                    cs_coroutine.start(function()
                        local row = goodsConfMgr:GetJumpModuleRow(taskVo.openType)
                        if row then
                            local vo = goodsConfMgr:GetGoodsVoById(taskVo.taskContentId)
                            cs_coroutine.yield_return(goodsConfMgr:ExecuteJump(row, vo, 0, false, {taskVo.openParameter}))
                        end
                        blocker:RemoveCondition("__ExecuteJump")
                    end)
                end, function()
                    print_to_file(debug.traceback())
                    blocker:RemoveCondition("__ExecuteJump")
                end)
            end
            if functionID == Constants.SystemToggleIds.Id3003 then
                ---外卖功能需要刷新下数据
                GameUtils.Request(Interfaces.MaidCoffeeTakeout, {}, function(req, response)
                    if checkNumber(response.errCode) == 0 then
                        local rdata = checkTable(response.data)
                        ---@type MaidCoffeePlayerComponent
                        local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
                        maidCoffeePlayerComponent:UpdateTakeOutDailyTimes(checkTable(rdata.dailyTimes))
                        maidCoffeePlayerComponent:ResetTakeoutOrders(checkTable(rdata.takeOutOrders))
                        jumpToTask()
                    end
                end)
            else
                jumpToTask()
            end
        end
    end
end


function UIMainChapterDialog:EnterQuest(id)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
    if not vo then
        return
    end
    
    
    if checkNumber(id) == Constants.QUEST_DOUBLE_GUIDE[1] then
        --self.controller:Close()
        --UIModule.CloseDialog(self.controller)
        --QTEReview = true
        --local QTEEntry = import("Game.QTE.QTEEntry")
        --QTEEntry:StartQTE()
        --return
    end

    --有任务 走跳转
    if checkNumber(vo.task) > 0 then
        self:OnTaskEnter(id)
        return
    end

    if checkNumber(vo.type) == Constants.QuestBattleType.Story then
        local goodsId = string.split(self.controller.goodIds, ";")
        self:PlayPlot(vo, function()
            local isRepeat = QuestConfMgr:GetInstance():IsRepeatQuest(id)
            questComponent:StoryEnterReq(id, function()
                local t = questComponent:GetShowRewardData()
                if t then
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = t, cb = function()
                        if not isRepeat then
                            if t then
                                for i, v in pairs(t) do
                                    for i, gId in pairs(goodsId) do
                                        if checkNumber(v.goodsId) == checkNumber(gId) then
                                            GameUtils.StartFlyGoods(self.CommonGoodsList.gameObject, checkNumber(v.goodsId))
                                        end
                                    end
                                end
                            end

                            --self:FillAllQuestNode()
                            self:PlayPassAni()
                            self:SetMainChapterBGM(id)
                        end
                    end } })
                else
                    if not isRepeat then
                        if t then
                            for i, v in pairs(t) do
                                for i, gId in pairs(goodsId) do
                                    if checkNumber(v.goodsId) == checkNumber(gId) then
                                        GameUtils.StartFlyGoods(self.CommonGoodsList.gameObject, checkNumber(v.goodsId))
                                    end
                                end
                            end
                        end

                        --self:FillAllQuestNode()
                        self:PlayPassAni()
                        self:SetMainChapterBGM(id)
                    end
                end
                local teamComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
                teamComp:UpdateEntrustRequeueData()
            end)
        end)
    else
        self:SetLastChallengeQuestId(id)

        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = id } }, {
            { id = Constants.UITypeIds.UIMainChapterDialog },
        })
    end
end

function UIMainChapterDialog:GetUnlockErr(questId)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not vo then
        return ""
    end
    local err
    if not QuestConfMgr:GetInstance():IsPassQuest(vo.unlockNum) then
        err = GameUtils.GetUnlockDescr(Constants.CommonUnlockType.PassQuest, checkString(vo.unlockNum))
    elseif not GameUtils.IsUnlocked(Constants.CommonUnlockType.PlayerLevel, checkString(vo.level)) then
        err = GameUtils.GetUnlockDescr(Constants.CommonUnlockType.PlayerLevel, checkString(vo.level))
    elseif not GameUtils.IsUnlocked(Constants.CommonUnlockType.TeamLevel, checkString(vo.teamLevel)) then
        err = localize("小队评级达到_num_解锁", { _num_ = CfUtils.GetTeamLevelSignByNum(vo.teamLevel)})
    end
    return err
end

