--播放剧情
function UIMainChapterDialog:PlayPlot(vo, endCb, isTask, taskStoryType)
    if not vo then
        return
    end
    if self.isPlayPlot then
        return
    end
    self.isPlayPlot = true

    local plotVo = QuestConfMgr:GetInstance():GetMainQuestPlotVo(vo.id)
    local plotIds = CfUtils.Split(plotVo.plotIdGroup2)


    if isTask then
        plotIds = {}
        --前置剧情
        if checkNumber(taskStoryType) == 1 then 
            local t = checkTable(CfUtils.Split(plotVo.taskPlotId))
            for k, v in pairs(t) do
                if checkNumber(v) > 0 then
                    table.insert(plotIds, v)
                end
            end
        elseif checkNumber(taskStoryType) == 3 then 
            local t = checkTable(CfUtils.Split(plotVo.taskPlotId))
            for k, v in pairs(t) do
                if checkNumber(v) > 0 then
                    table.insert(plotIds, v)
                end
            end
            t = checkTable(CfUtils.Split(plotVo.taskPlotEndId))
            for k, v in pairs(t) do
                if checkNumber(v) > 0 then
                    table.insert(plotIds, v)
                end
            end
        else
            local t = checkTable(CfUtils.Split(plotVo.taskPlotEndId))
            for k, v in pairs(t) do
                if checkNumber(v) > 0 then
                    table.insert(plotIds, v)
                end
            end
        end
    end
    if not plotIds or (table.count(plotIds) < 0) then
        if endCb then
            endCb()
        end
        self.isPlayPlot = false
        --GameUtils.Toast(localize("该关卡没有剧情参数"))
        return 
    end

    self.curPlotIndex = 1
    self:PlayPloting(plotIds, vo, endCb)
end

function UIMainChapterDialog:PlayPloting(plotIds, vo, endCb)
    local cacheTimelineLoader = nil
    local plotId = checkNumber(plotIds[self.curPlotIndex])
    ChapterUtils.ProcessChapter(plotId, function(go)
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
        self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
        URPCameraController:SetMainCameraActive(false)
        UINavigationBarRoot.Instance:SetActive(false)
        self._plotGo = go

        -- 如果下一段是timeline剧情，预加载一下
        if self.curPlotIndex < table.count(plotIds) then
            local vo = ChapterUtils.GetChapterGeneralVo(checkNumber(plotIds[self.curPlotIndex + 1]))
            if vo and not string.isEmpty(vo.timelinePath) then
                cacheTimelineLoader = ResourceModule.LoadBundleAsync(vo.timelinePath)
                cacheTimelineLoader:Retain()
                -- print("[加载] 预加载", checkNumber(plotIds[self.curPlotIndex + 1]), vo.timelinePath)
            end
        end
    end, function()
        --所有的播完结束
        if self.curPlotIndex >= table.count(plotIds) then
            self:PlayCurBgm()
            if endCb then
                endCb()
            end

            self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
            URPCameraController:SetMainCameraActive(true)
            UINavigationBarRoot.Instance:SetActive(true)
            KTool.SafeDelete(self._plotGo)
            self.isPlayPlot = false

            --MainQuestMapMgr:GetInstance():RefreshCam()
        else
            self.curPlotIndex = self.curPlotIndex + 1
            KTool.SafeDelete(self._plotGo)
            self:PlayPloting(plotIds, vo, endCb)
        end
        -- 释放预加载的引用
        if cacheTimelineLoader then
            cacheTimelineLoader:Release()
            -- print("[加载] 释放预加载", checkNumber(plotIds[self.curPlotIndex]), vo.timelinePath)
        end
    end, nil, function()
        -- 每段剧情之间加一个黑幕
        if self.curPlotIndex < table.count(plotIds) then
            GameUtils.ShowBlackDuration(0.4, 0.3, 0.4)
            coroutine.yield(Yielders.GetWaitForSeconds(0.4))
        end
    end)
end

