function UIMainChapterDialog:OnBtnMopUpClick()
    local isBoss =  self:IsBoss()
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._curSelectId)
    if isBoss and isPass then
        ---@type QuestComponent
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
        local isCanEnter = comp:IsCanEnterHardChapter()
        if isCanEnter then
            UIModule.OpenDialog({ id = Constants.UITypeIds.UISweepPrepareDialog, parameters = { questId = self._curSelectId } })
        else
            GameUtils.Toast(localize("剩余奖励次数不足"))
        end
    else
        GameUtils.Toast(localize("首次通关后解锁扫荡"))
    end
end

function UIMainChapterDialog:IsBoss()
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectId)
    if not isNull(vo) then
        local isSmallBoss =checkNumber(vo.monsteType) == Constants.RoleClass.Boss
        return isSmallBoss
    end
    return false
end

function UIMainChapterDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        coroutine.yield(MainQuestMapMgr:GetInstance():Init())
        local isTrue = false
        GameUtils.Request(Interfaces.TaskMainTaskHome, {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                local responseData = checkTable(response.data)
                questComponent:RefreshQuestInfo(responseData.mainTaskInfo)

                isTrue = true
            end
        end)

        while not isTrue do
            coroutine.yield(Yielders.EndOfFrame)
        end

        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
    
        self._curChapterId = checkNumber(argument.chapterId)  
        self._curType = checkNumber(argument.type)  
        self._curSelectId = checkNumber(argument.targetId)
    
        if self._curChapterId <= 0 then
            return
        end
        if self._curType <= 0 then
            self._curType = Constants.IDType.QuestMain
        end
        --先根据类型刷ID
        self:RefreshCurSelectId()
        --再根据最终ID决定类型
        if self._curSelectId > 0 then
            self._curType = GoodsUtils.GetIdType(self._curSelectId, Constants.IDArea.Quests)
        end 
    
        self:InitData()
        self:FillSelf()
    
        self:FillRedPoint()

        local status = self:IsMainChapter() and 1 or 2
        CfUtils.SetUISwitchImage(self.controller.gameObject.transform:Find("BgContainer/Imgtext3"), status)
        CfUtils.SetUISwitchImage(self.controller.gameObject.transform:Find("DetailsShowGroup/AimRoot/FrameGroup/Img1"), status)
        CfUtils.SetUISwitchImage(self.controller.gameObject.transform:Find("DetailsShowGroup/AimRoot/FrameGroup/Img2"), status)
        CfUtils.SetUISwitchImage(self.controller.gameObject.transform:Find("DetailsShowGroup/AimRoot/FrameGroup/Img3"), status)
        CfUtils.SetUISwitchText(self.TxtNumber, status)
        CfUtils.SetUISwitchText(self.TxtName, status)
        CfUtils.SetActive(self.TxtHard, status == 2)
    
        CfUtils.SetActive(self.controller.gameObject.transform:Find("Container/LeftPanel/ChapterTitle/MusicPlayer/Story"), status == 1)
        CfUtils.SetActive(self.controller.gameObject.transform:Find("Container/LeftPanel/ChapterTitle/MusicPlayer/Challenge"), status == 2)

        -- 播放主线章节BGM
        local bgmId = QuestConfMgr:GetInstance():GetCurrentMainChapterBGM()
        if not string.isEmpty(bgmId) then
            CriWareUtils.PlayMusicById(bgmId)
        end
    end))
    return coWait
end

function UIMainChapterDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(Constants.EventNames.MainQuestTaskChange, self.EventMainQuestTaskChange)

        playerComponent:StopMainChapterExtraDialog()

        local id = CfUtils.GetLocalData("MainChapterShowMovie")
        if checkNumber(self._curChapterId) > checkNumber(id) then
            CfUtils.WriteLocalData("MainChapterShowMovie", self._curChapterId)
        end

        if not isNull(self._headPool) then
            for k, v in pairs(self._headPool) do
                GameObject.Destroy(v)
            end
        end
        if not isNull(self._loaderPool) then
            for k, v in pairs(self._loaderPool) do
                v:Release(true)
            end
        end

        if not isNull(self) then
            if self._headCo then
                cs_coroutine.stop(self._headCo)
                self._headCo = nil
            end

            if self._taskCo then
                cs_coroutine.stop(self._taskCo)
                self._taskCo = nil
            end
            if self._co then
                cs_coroutine.stop(self._co)
                self._co = nil
            end
            if self._passCo then
                cs_coroutine.stop(self._passCo)
                self._passCo = nil
            end
            if self._Sideco then
                cs_coroutine.stop(self._Sideco)
                self._Sideco = nil
            end
            if self._btnCo then
                cs_coroutine.stop(self._btnCo)
                self._btnCo = nil
            end
        end
        MainQuestMapMgr:GetInstance():Clear()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function UIMainChapterDialog:SetMainChapterBGM(questId)
    -- 设置主界面BGM
    local vo = QuestConfMgr:GetInstance():GetMainQuestPlotVo(questId)
    CS.Engine.Lib.KCookie.Set("MainChapterFirstPassBGM", vo.music)
    print("[BGM] 主线首通", questId, vo.music)
end

return UIMainChapterDialog
